import{_ as o,l as s,o as a,c as n,v as t,p as l,x as r,d as p,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"深流水与时钟频率","description":"","frontmatter":{"title":"深流水与时钟频率","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deep-pipeline-clock.md","filePath":"cs/deep-pipeline-clock.md","lastUpdated":1789023840000}'),d={name:"cs/deep-pipeline-clock.md"};function A(h,e,P,m,_,u){const i=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="深流水与时钟频率" tabindex="-1">深流水与时钟频率 <a class="header-anchor" href="#深流水与时钟频率" aria-label="Permalink to &quot;深流水与时钟频率&quot;">​</a></h1><div class="epigraph"><p>切更多级可以抬高频率，但误预测要填的级数也变多；最优深度随预测准确率、工作负载和功耗一起动，不是越深越快。</p><footer>—— 据 Hartstein and Puzak, The Optimum Pipeline Depth for a Microprocessor, ISCA 2002；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/retire-precise-exception">上一课</a> 把架构写钉在 ROB 头，并指出级深会放大冲刷量。<a href="/cs/pipeline-five-stage">五级</a> 已经用切段换频率。本课不重讲精确异常。缺口是<strong>乱序核把流水切到 15–30 级时，时钟与误预测损失如何一起进入 CPI 公式</strong>——Pentium 4 式超深流水的教训。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想情况下，级深加倍则时钟近加倍，同一 IPC 下吞吐加倍。但 <a href="/cs/gshare-predictor">gshare</a> 的损失拍 ≈ 从 IF 到核对的级数；窗口更大、恢复更重，<a href="/cs/speculation-recovery">推测恢复</a> 更贵。功耗随触发器数量与旁路上升。缺口不是再加一个退休口，而是<strong>把频率收益与每条指令的额外停顿、能耗放在同一张账上</strong>。</p><p><span class="marginnote">Hartstein–Puzak 用解析与模拟指出：存在最优流水深度；预测变差或能耗权重大时，最优点变浅。Pentium 4 的长管线后来被更短、更宽的核取代，是这条曲线的工业注脚。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把单指令延迟写成「级数 × 周期」。吞吐仍是每拍 uop 数。优化目标可以是性能、性能/瓦或 SPEC 分数。设计旋钮：切哪一段（ALU 旁路、数据 cache 命中、前端译码）、是否加转发跨越更多级、是否用半周期设计。</p>',8)),(a(),l(E,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEEP%5B%22%E5%8A%A0%E6%B7%B1%E7%BA%A7%E6%95%B0%22%5D%20--%3E%20FREQ%5B%22%E5%91%A8%E6%9C%9F%E7%BC%A9%E7%9F%AD%22%5D%0A%20%20DEEP%20--%3E%20PEN%5B%22%E8%AF%AF%E9%A2%84%E6%B5%8B%E5%A1%AB%E7%AE%A1%E6%9B%B4%E8%B4%B5%22%5D%0A%20%20DEEP%20--%3E%20FF%5B%22%E8%A7%A6%E5%8F%91%E5%99%A8%E4%B8%8E%E6%97%81%E8%B7%AF%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20FREQ%20--%3E%20PERF%5B%22%E5%8F%AF%E8%83%BD%E6%8F%90%E9%AB%98%E5%90%9E%E5%90%90%22%5D%0A%20%20PEN%20--%3E%20PERF%0A%20%20FF%20--%3E%20PWR%5B%22%E5%8A%9F%E8%80%97%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>：停顿项里控制冒险随级深近似线性涨，数据转发失败的气泡也涨。若工作负载分支密、预测不准，加深会让有效 CPI 涨得比频率更快，净时间变差。乱序窗口可以掩盖部分数据延迟，但掩盖不了「整条错误路径上的前端填充」。</p><p>这门课序在前端与乱序核收束：预测、重命名、IQ、LSQ、前端缓存、退休、级深，共同决定单核 ILP。下一单元转向 cache 替换与一致性协议的进阶细节。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选某个商业核的级数当标准答案。也不把多发射、多核当成「加深」的替代公式——那是并行课。功耗模型只到「触发器与投机浪费」，不去工艺库。</p><p>后课默认：更深不是自动更快；准确预测是深管线的许可证。单元切换：替换策略从 LRU 讲起，不再加宽前端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>级深抬频率，同时抬误预测与功耗；存在最优深度。</li><li>乱序掩盖数据延迟，掩盖不了错误路径的填充。</li><li>下一课序从 cache 替换（LRU/PLRU）接上。</li><li>出处：Hartstein and Puzak, <em>ISCA</em>, 2002；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const F=o(d,[["render",A]]);export{f as __pageData,F as default};
